 I('ripple','Ripple Stone','◎','common','Shots create a second splash on impact.','ripple'), I('candle','Blue Candle','♧','common','Active relic recharges more quickly.','charge'), I('harpoon','Harpoon Crown','↗','rare','Every fourth shot marks foes for bonus damage.','mark'), I('cocoon','Cocoon of Sleep','❀','rare','First strike on a room’s foes hits harder.','ambush'), I('crown','Crown of Silt','♛','rare','A dangerous relic: faster fire, less health.','curse')
];
export const RELICS = [
 {name:'TIDECALL',icon:'ϟ',cooldown:9,desc:'A bolt finds your target.'}, {name:'BRINE VEIL',icon:'◌',cooldown:14,desc:'Become briefly untouchable.'}, {name:'SALT BLOOM',icon:'✿',cooldown:16,desc:'Burst with a ring of saltfire.'}, {name:'ECHO VIAL',icon:'♢',cooldown:18,desc:'Repeat your last volley.'}
];

import {BIOMES,ENEMIES,ITEMS} from './data.js';

export function makeRng(seed){let s=(Number(seed)>>>0)||0x51ab1e;return()=>{s+=0x6D2B79F5;let t=s;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return((t^(t>>>14))>>>0)/4294967296}}
export const pick=(rng,arr)=>arr[Math.floor(rng()*arr.length)];
const key=(x,y)=>`${x},${y}`;
export function generateFloor(seed,floor=1){
 const rng=makeRng(seed+floor*7919), rooms=[], byPos=new Map();
 const add=(x,y,type,depth)=>{const r={id:key(x,y),x,y,type,depth,cleared:false,visited:false,doors:[],encounter:[],reward:null};rooms.push(r);byPos.set(r.id,r);return r};
 let cur=add(0,0,'start',0);const main=[cur],used=new Set([cur.id]);
 for(let i=1;i<=5;i++){
  let opts=[[1,0],[0,1],[0,-1]];if(i===5)opts=[[1,0]];
  let [dx,dy]=opts[Math.floor(rng()*opts.length)];let p=[cur.x+dx,cur.y+dy];let tries=0;
  while(used.has(key(...p))&&tries++<8){[dx,dy]=opts[(opts.indexOf(opts.find(v=>v[0]===dx&&v[1]===dy))+1)%opts.length];p=[cur.x+dx,cur.y+dy]}
  cur=add(p[0],p[1],i===5?'boss':'combat',i);used.add(cur.id);main.push(cur);
 }
 main[2].type='treasure';
 for(const source of [main[1],main[3]])if(rng()<.75){const opts=[[0,1],[0,-1],[1,0],[-1,0]].sort(()=>rng()-.5);for(const [dx,dy] of opts){const id=key(source.x+dx,source.y+dy);if(!used.has(id)){const type=rng()<.45?'shop':rng()<.5?'event':'combat';add(source.x+dx,source.y+dy,type,source.depth);used.add(id);break}}}
 for(let i=0;i<rooms.length;i++)for(let j=i+1;j<rooms.length;j++){let a=rooms[i],b=rooms[j];if(Math.abs(a.x-b.x)+Math.abs(a.y-b.y)===1){a.doors.push(b.id);b.doors.push(a.id)}}
 const biome=BIOMES[(floor-1)%BIOMES.length];
 for(const r of rooms){
  if(r.type==='start'){r.cleared=true;continue}
  if(r.type==='treasure'){r.reward=pick(rng,ITEMS);continue}
  if(r.type==='shop'){r.reward=pick(rng,ITEMS);continue}
  if(r.type==='event'){r.reward=pick(rng,['heal','coins','item']);continue}
  const count=r.type==='boss'?1:Math.min(5,2+Math.floor(r.depth/2)+Math.floor(rng()*2));
  for(let n=0;n<count;n++){let enemy=pick(rng,ENEMIES.slice(0,Math.min(ENEMIES.length,7+floor*2)));r.encounter.push({type:enemy.name,x:92+rng()*236,y:240+rng()*260,hp:enemy.hp*(1+(floor-1)*.18),maxHp:enemy.hp*(1+(floor-1)*.18),variant:Math.floor(rng()*9999)})}
  if(r.type==='boss')r.encounter=[{type:biome.boss,x:210,y:360,hp:260+floor*40,maxHp:260+floor*40,variant:floor}];
 }
 return {seed,floor,biome,rooms,start:main[0].id,boss:main[5].id};
}

import {BIOMES,CHARACTERS,ENEMIES,ITEMS,RELICS} from './data.js';
import {generateFloor,makeRng,pick} from './generator.js';
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
const dirs={left:[-1,0],right:[1,0],up:[0,-1],down:[0,1]};
const enemyDef=name=>ENEMIES.find(e=>e.name===name)||{name,kind:'boss',hp:300,speed:45,damage:2,range:200,color:'#b187d5',threat:5,score:4,shape:'eye'};
export class AbyssalGame{
 constructor(){this.settings=Object.assign({hand:'right',stickSize:1,sensitivity:1,auto:true,sound:true},this.load('abyssal-settings',{}));this.meta=Object.assign({unlocked:['mara','oss'],wins:0,losses:0,kills:0,bestFloor:1,runs:0,items:[],achievements:[]},this.load('abyssal-meta',{}));this.state='title';this.character=CHARACTERS[0];this.entities=[];this.shots=[];this.particles=[];this.room=null;this.floor=null;this.mapOpen=false;this.pauseFrom='playing';this.input={x:0,y:0,aim:null,manual:false};this.elapsed=0;this.notice='';this.noticeTimer=0;this.pickup=null;this.lastShot=0;this.seed=0;this.rng=Math.random;this.touch={joy:null,joyOrigin:null,aiming:false};this.audioCtx=null;this.score=0;this.floorKills=0;this.runItems=[];this.obstacles=[];this.orbitAngle=0;this.aimMode=false;this.message='';this.messageTimer=0;this.activeRelic=RELICS[0];this.buttons=[];this.roomNumber=0;this.transitionLock=0;this.shake=0;this.sfxCooldown=0}
 load(k,f){try{return JSON.parse(localStorage.getItem(k))||f}catch{return f}}
 save(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{}}
 persist(){this.save('abyssal-meta',this.meta);this.save('abyssal-settings',this.settings)}
 announce(text){this.message=text;this.messageTimer=2.2;document.getElementById('live').textContent=text}
 startRun(seed){this.seed=(Number(seed)>>>0)||Math.floor(Math.random()*999999999);this.rng=makeRng(this.seed);this.floorIndex=1;this.floor=generateFloor(this.seed,1);this.roomId=this.floor.start;this.roomNumber=0;this.score=0;this.floorKills=0;this.runItems=[];this.player={x:210,y:480,hp:this.character.hp,maxHp:this.character.hp,speed:this.character.speed,damage:this.character.damage,rate:this.character.rate,range:this.character.range,shot:this.character.shot,luck:this.character.luck,defense:this.character.defense,coins:3,faceX:0,faceY:-1,invuln:0,dash:0,dashCd:0,abilityCd:0,relicCd:0,shield:0,shotsFired:0,roomFirst:true,flags:{},effects:[],fireTimer:0};this.state='playing';this.openRoom(this.roomId,true);this.meta.runs++;this.meta.bestFloor=Math.max(this.meta.bestFloor,this.floorIndex);this.persist();this.announce(`SEED ${this.seed} · ${this.floor.biome.name}`)}
 chooseCharacter(id){let c=CHARACTERS.find(x=>x.id===id);if(!c)return;if(c.unlock&&!this.meta.unlocked.includes(id)){this.announce('CLEAR A FLOOR TO UNLOCK NYX-7');return}this.character=c;this.state='playing';this.startRun(this.seedInput||undefined)}
 openRoom(id,first=false){this.roomId=id;this.room=this.floor.rooms.find(r=>r.id===id);this.room.visited=true;this.roomNumber++;this.entities=[];this.shots=[];this.particles=[];this.pickup=null;this.transitionLock=.5;this.player.x=210;this.player.y=first?480:465;this.player.invuln=1.1;this.player.roomFirst=true;this.obstacles=[];let rng=makeRng(this.seed+this.floorIndex*9187+this.roomNumber*313);
  for(let i=0;i<2;i++){let x=120+rng()*180,y=270+rng()*180;if(Math.hypot(x-this.player.x,y-this.player.y)>110)this.obstacles.push({x,y,w:25+rng()*20,h:18+rng()*12})}
  if(this.room.type==='treasure'||this.room.type==='shop'){this.room.cleared=true;this.pickup=this.room.reward;this.announce(this.room.type==='shop'?'A TIDEWORN TRADER':'A RELIC REMEMBERS YOU')}else{this.entities=this.room.encounter.map((e,i)=>{const d=enemyDef(e.type);return{...e,id:i,def:d,x:e.x,y:e.y,hp:e.hp,maxHp:e.maxHp,attackCd:1+rng()*1.5,stun:0,burn:0,poison:0,frost:0,flash:0,phase:0,charge:0,teleport:0,marked:0}});this.room.cleared=this.entities.length===0}
  if(this.room.type==='event'&&this.room.reward){if(this.room.reward==='heal')this.player.hp=Math.min(this.player.maxHp,this.player.hp+1);else if(this.room.reward==='coins')this.player.coins+=5;else this.pickup=pick(this.rng,ITEMS)}
 }
 getDirections(){return this.room?.doors.map(id=>({id,room:this.floor.rooms.find(r=>r.id===id)}))||[]}
 transition(id){if(this.transitionLock>0||!this.room.cleared)return;let r=this.floor.rooms.find(v=>v.id===id);if(!r)return;this.score+=10;this.openRoom(id);if(r.type==='boss'&&r.cleared)this.clearBoss()}
 clearBoss(){this.floorCleared=true;this.state='floorclear';this.player.hp=Math.min(this.player.maxHp,this.player.hp+1);this.player.coins+=5;this.announce('THE GUARDIAN FALLS · THE TIDE RECEDES')}
 nextFloor(){if(this.floorIndex>=3){this.state='victory';this.meta.wins++;this.meta.bestFloor=Math.max(this.meta.bestFloor,3);this.unlockOnWin();this.persist();return}this.floorIndex++;this.floor=generateFloor(this.seed,this.floorIndex);this.roomId=this.floor.start;this.openRoom(this.roomId,true);this.player.hp=Math.min(this.player.maxHp,this.player.hp+1);this.player.roomFirst=true;this.state='playing';this.meta.bestFloor=Math.max(this.meta.bestFloor,this.floorIndex);this.persist();this.announce(this.floor.biome.name)}
 unlockOnWin(){if(!this.meta.unlocked.includes('nyx'))this.meta.unlocked.push('nyx');this.addAchievement('THREE BELOW');this.persist()}
 addAchievement(id){if(!this.meta.achievements.includes(id))this.meta.achievements.push(id)}
 itemTake(item){if(!item)return;if(typeof item==='string'){if(item==='heal')this.player.hp=Math.min(this.player.maxHp,this.player.hp+2);else this.player.coins+=4;return}this.runItems.push(item);this.meta.items=Array.from(new Set([...this.meta.items,item.id]));this.applyItem(item.effect);if(item.effect==='shell')this.player.shield=1;if(item.effect==='ward')this.player.shield=2;if(item.effect==='crown'){this.player.rate*=.8;this.player.hp=Math.max(1,this.player.hp-1)}this.player.roomFirst=false;this.persist();this.announce(`${item.name} · ${item.desc}`);this.pickup=null}
 applyItem(effect){let p=this.player;p.flags[effect]=(p.flags[effect]||0)+1;switch(effect){case'ember':case'flare':p.damage*=1.08;break;case'needle':p.flags.pierce++;break;case'many':case'spread':p.flags.spread++;break;case'choir':case'echo':p.flags.echo++;break;case'glass':case'crit':p.flags.crit++;break;case'fang':p.flags.fang++;break;case'void':p.range+=45;break;case'gale':p.speed+=8;break;case'compass':p.luck+=1;break;case'candle':case'charge':p.relicCd*=.75;break;case'marrow':case'mend':p.maxHp++;p.hp++;break;case'crown':p.rate*=.8;p.hp=Math.max(1,p.hp-1);break;case'ward':p.shield=2;break}}
 damageEnemy(e,amount,kind='shot'){if(e.hp<=0)return;let dmg=amount;if(this.player.flags.fang&&dist(e,this.player)<75)dmg*=1.35;if(e.marked>0)dmg*=1.3;e.hp-=dmg;e.flash=.14;if(kind==='burn')e.burn=Math.max(e.burn,3);if(kind==='poison')e.poison=Math.max(e.poison,4);if(kind==='frost')e.frost=Math.max(e.frost,1.3);if(kind==='stun')e.stun=Math.max(e.stun,.7);if(this.player.flags.stagger)e.stun=Math.max(e.stun,.18);if(this.player.flags.push){let a=Math.atan2(e.y-this.player.y,e.x-this.player.x);e.x+=Math.cos(a)*12;e.y+=Math.sin(a)*12}this.particles.push({x:e.x,y:e.y,life:.27,max:.27,color:e.def.color,type:'hit'});if(e.hp<=0)this.killEnemy(e)}
 killEnemy(e){if(e.dead)return;e.dead=true;this.floorKills++;this.meta.kills++;this.score+=Math.round(20*e.def.score);this.player.coins+=this.rng()<.24?1:0;if(this.player.flags.leech&&this.rng()<.36)this.player.hp=Math.min(this.player.maxHp,this.player.hp+1);if(this.player.flags.mend&&this.entities.every(v=>v===e||v.dead))this.player.hp=Math.min(this.player.maxHp,this.player.hp+1);if(this.player.flags.fork)this.fireShot(e.x,e.y,0,-1,.5,'fork');if(this.player.flags.spore){for(let q of this.entities)if(q!==e&&!q.dead&&dist(q,e)<95)this.damageEnemy(q,8,'poison')};for(let i=0;i<7;i++)this.particles.push({x:e.x,y:e.y,vx:(this.rng()-.5)*140,vy:(this.rng()-.5)*140,life:.4+this.rng()*.3,max:.7,color:e.def.color,type:'silt'})}
 pickTarget(){let best=null,bestScore=-1e9,p=this.player;for(let e of this.entities){if(e.dead)continue;let dx=e.x-p.x,dy=e.y-p.y,d=Math.hypot(dx,dy);if(d>p.range+50)continue;let vx=e.vx||0,vy=e.vy||0,approach=d?-(dx*vx+dy*vy)/d:0;let blocked=this.obstacles.some(o=>lineRect(p.x,p.y,e.x,e.y,o));if(blocked)continue;let score=e.def.threat*33-d*.22+approach*.16+(e.def.kind==='charge'?18:0)+(e.def.kind==='ranged'?6:0);if(this.player.flags.compass)score+=e.def.threat*10;if(score>bestScore){bestScore=score;best=e}}return best}
 fireShot(x,y,dx,dy,mult=1,kind='normal'){let l=Math.hypot(dx,dy)||1;dx/=l;dy/=l;let p=this.player,flags=p.flags;this.shots.push({x,y,vx:dx*p.shot,vy:dy*p.shot,damage:p.damage*mult,life:p.range/p.shot,pierce:flags.pierce?1+flags.pierce:0,bounce:flags.bounce?1:0,kind:flags.prism?'prism':flags.ember||flags.flare?'fire':flags.frost?'frost':flags.poison||flags.rot?'poison':'normal',homing:!!(flags.homing||flags.lantern),echo:false});this.player.faceX=dx;this.player.faceY=dy;this.player.shotsFired++;if(flags.echo&&this.player.shotsFired%2===0)this.shots.push({x,y,vx:dx*p.shot*.78,vy:dy*p.shot*.78,damage:p.damage*.55,life:p.range/p.shot,pierce:0,bounce:0,kind:'echo',homing:false});if(flags.twin)this.shots.push({x:x-dy*7,y:y+dx*7,vx:dx*p.shot,vy:dy*p.shot,damage:p.damage*.5,life:p.range/p.shot,pierce:0,bounce:0,kind:'echo',homing:false});if(flags.spread)for(let i=1;i<=flags.spread+1;i++)for(let s of [-1,1]){let a=Math.atan2(dy,dx)+s*.24*i;this.shots.push({x,y,vx:Math.cos(a)*p.shot*.9,vy:Math.sin(a)*p.shot*.9,damage:p.damage*.62,life:p.range/p.shot,pierce:flags.pierce?1:0,bounce:0,kind:flags.ember?'fire':'normal',homing:false})}if(flags.mirror&&this.player.shotsFired%3===0)this.shots.push({x,y,vx:-dx*p.shot,vy:-dy*p.shot,damage:p.damage*.6,life:p.range/p.shot,pierce:0,bounce:0,kind:'echo'});this.sfx('shot')}
