 updateEnemies(dt){let p=this.player;for(let e of this.entities){if(e.dead)continue;let d=dist(e,p),dx=(p.x-e.x)/(d||1),dy=(p.y-e.y)/(d||1),def=e.def;e.flash=Math.max(0,e.flash-dt);e.stun=Math.max(0,e.stun-dt);e.burn=Math.max(0,e.burn-dt);e.poison=Math.max(0,e.poison-dt);e.frost=Math.max(0,e.frost-dt);e.marked=Math.max(0,e.marked-dt);e.attackCd-=dt;if(e.burn>0&&Math.floor((e.burn+dt)*3)>Math.floor(e.burn*3))this.damageEnemy(e,2,'dot');if(e.poison>0&&Math.floor((e.poison+dt)*2)>Math.floor(e.poison*2))this.damageEnemy(e,1.5,'dot');if(e.dead)continue;if(e.stun>0)continue;let slow=e.frost>0?.48:1;let speed=def.speed*slow;let kind=def.kind;let vx=0,vy=0;
