const http = require('http');
const fs = require('fs');
const path = require('path');
const root = process.cwd();
const server = http.createServer((req,res)=>{
  let p = req.url === '/' ? '/index.html' : req.url.split('?')[0];
  const file = path.join(root, p);
  if (!file.startsWith(root)) { res.statusCode=403; res.end('forbidden'); return; }
  fs.readFile(file, (err, data) => {
    if (err) { res.statusCode = 404; res.end('missing'); return; }
    const type = file.endsWith('.js') ? 'application/javascript' : file.endsWith('.css') ? 'text/css' : 'text/html';
    res.setHeader('Content-Type', type + '; charset=utf-8');
    res.end(data);
  });
});
server.listen(3003, ()=> console.log('ready',3003));
