8:  constructor(){this.settings=Object.assign({hand:'right',stickSize:1,sensitivity:1,auto:true,sound:true},this.load('abyssal-settings',{}));this.meta=Object.assign({unlocked:['mara','oss'],wins:0,losses:0,kills:0,bestFloor:1,runs:0,items:[],achievements:[]},this.load('abyssal-meta',{}));this.state='title';this.character=CHARACTERS[0];this.entities=[];this.shots=[];this.particles=[];this.room=null;this.floor=null;this.mapOpen=false;this.pauseFrom='playing';this.input={x:0,y:0,aim:null,manual:false};this.elapsed=0;this.notice='';this.noticeTimer=0;this.pickup=null;this.lastShot=0;this.seed=0;this.rng=Math.random;this.touch={joy:null,joyOrigin:null,aiming:false};this.audioCtx=null;this.score=0;this.floorKills=0;this.runItems=[];this.obstacles=[];this.orbitAngle=0;this.aimMode=false;this.message='';this.messageTimer=0;this.activeRelic=RELICS[0];this.buttons=[];this.roomNumber=0;this.transitionLock=0;this.shake=0;this.sfxCooldown=0}
