13:  startRun(seed){this.seed=(Number(seed)>>>0)||Math.floor(Math.random()*999999999);this.rng=makeRng(this.seed);this.floorIndex=1;this.floor=generateFloor(this.seed,1);this.roomId=this.floor.start;this.roomNumber=0;this.score=0;this.floorKills=0;this.runItems=[];this.player={x:210,y:480,hp:this.character.hp,maxHp:this.character.hp,speed:this.character.speed,damage:this.character.damage,rate:this.character.rate,range:this.character.range,shot:this.character.shot,luck:this.character.luck,defense:this.character.defense,coins:3,faceX:0,faceY:-1,invuln:0,dash:0,dashCd:0,abilityCd:0,relicCd:0,shield:0,shotsFired:0,roomFirst:true,flags:{},effects:[],fireTimer:0};this.state='playing';this.openRoom(this.roomId,true);this.meta.runs++;this.meta.bestFloor=Math.max(this.meta.bestFloor,this.floorIndex);this.persist();this.announce(`SEED ${this.seed} · ${this.floor.biome.name}`)}
14:  chooseCharacter(id){let c=CHARACTERS.find(x=>x.id===id);if(!c)return;if(c.unlock&&!this.meta.unlocked.includes(id)){this.announce('CLEAR A FLOOR TO UNLOCK NYX-7');return}this.character=c;this.state='playing';this.startRun(this.seedInput||undefined)}
