27:  applyItem(effect){let p=this.player;p.flags[effect]=(p.flags[effect]||0)+1;switch(effect){case'ember':case'flare':p.damage*=1.08;break;case'needle':p.flags.pierce++;break;case'many':case'spread':p.flags.spread++;break;case'choir':case'echo':p.flags.echo++;break;case'glass':case'crit':p.flags.crit++;break;case'fang':p.flags.fang++;break;case'void':p.range+=45;break;case'gale':p.speed+=8;break;case'compass':p.luck+=1;break;case'candle':case'charge':p.relicCd*=.75;break;case'marrow':case'mend':p.maxHp++;p.hp++;break;case'crown':p.rate*=.8;p.hp=Math.max(1,p.hp-1);break;case'ward':p.shield=2;break}}
28:  damageEnemy(e,amount,kind='shot'){if(e.hp<=0)return;let dmg=amount;if(this.player.flags.fang&&dist(e,this.player)<75)dmg*=1.35;if(e.marked>0)dmg*=1.3;e.hp-=dmg;e.flash=.14;if(kind==='burn')e.burn=Math.max(e.burn,3);if(kind==='poison')e.poison=Math.max(e.poison,4);if(kind==='frost')e.frost=Math.max(e.frost,1.3);if(kind==='stun')e.stun=Math.max(e.stun,.7);if(this.player.flags.stagger)e.stun=Math.max(e.stun,.18);if(this.player.flags.push){let a=Math.atan2(e.y-this.player.y,e.x-this.player.x);e.x+=Math.cos(a)*12;e.y+=Math.sin(a)*12}this.particles.push({x:e.x,y:e.y,life:.27,max:.27,color:e.def.color,type:'hit'});if(e.hp<=0)this.killEnemy(e)}
29:  killEnemy(e){if(e.dead)return;e.dead=true;this.floorKills++;this.meta.kills++;this.score+=Math.round(20*e.def.score);this.player.coins+=this.rng()<.24?1:0;if(this.player.flags.leech&&this.rng()<.36)this.player.hp=Math.min(this.player.maxHp,this.player.hp+1);if(this.player.flags.mend&&this.entities.every(v=>v===e||v.dead))this.player.hp=Math.min(this.player.maxHp,this.player.hp+1);if(this.player.flags.fork)this.fireShot(e.x,e.y,0,-1,.5,'fork');if(this.player.flags.spore){for(let q of this.entities)if(q!==e&&!q.dead&&dist(q,e)<95)this.damageEnemy(q,8,'poison')};for(let i=0;i<7;i++)this.particles.push({x:e.x,y:e.y,vx:(this.rng()-.5)*140,vy:(this.rng()-.5)*140,life:.4+this.rng()*.3,max:.7,color:e.def.color,type:'silt'})}
